package com.example.rokidgeminisecretary;
import android.app.*;import android.widget.*;import org.json.*;
final class ReadingHistoryDialog {
 static void list(MainActivity owner){new Thread(()->{try{JSONArray rows=ReadingHistory.list(owner);String[] labels=new String[rows.length()];for(int i=0;i<labels.length;i++){JSONObject row=rows.getJSONObject(labels.length-1-i);labels[i]=new java.util.Date(row.getLong("at"))+" / "+row.optString("question");}owner.runOnUiThread(()->new AlertDialog.Builder(owner).setTitle("読み取り・訂正履歴（100件・90日）").setItems(labels,(d,index)->show(owner,rows.optJSONObject(rows.length()-1-index).optString("id"))).setPositiveButton("閉じる",null).show());}catch(Exception e){owner.runOnUiThread(()->Toast.makeText(owner,"履歴を取得できません。元データは保持しています",Toast.LENGTH_LONG).show());}},"ReadingHistory").start();}
 static void show(MainActivity owner,String id){new Thread(()->{try{JSONObject row=ReadingHistory.get(owner,id);owner.runOnUiThread(()->{LinearLayout box=new LinearLayout(owner);box.setOrientation(1);box.setPadding(20,12,20,12);if(!row.optString("thumbnail").isEmpty())try{byte[] bytes=android.util.Base64.decode(row.getString("thumbnail"),2);android.graphics.Bitmap bitmap=android.graphics.BitmapFactory.decodeByteArray(bytes,0,bytes.length);if(bitmap!=null){ImageView image=new ImageView(owner);image.setImageBitmap(bitmap);image.setAdjustViewBounds(true);image.setMaxHeight(240);box.addView(image);}}catch(Exception ignored){}TextView text=new TextView(owner);text.setTextIsSelectable(true);StringBuilder body=new StringBuilder("保存されている縮小プレビューです。原寸画像の保存ではありません。\n元の読み取り（変更しません）\n"+row.optString("answer")+"\n\n訂正履歴（予定やAIの参照データへ自動反映しません）");JSONArray edits=row.optJSONArray("corrections");for(int i=0;edits!=null&&i<edits.length();i++){JSONObject c=edits.optJSONObject(i);body.append("\n").append(c.optString("field")).append("：").append(c.optString("before").isEmpty()?"変更前未指定":c.optString("before")).append(" → ").append(c.optString("after"));}text.setText(body);box.addView(text);Button compose=new Button(owner);compose.setText("訂正を含めて会話入力へ（未送信）");compose.setOnClickListener(v->{try{owner.composeLocalReview(ReadingCorrectionContext.prepare(owner,id,row.getInt("revision")).getString("text"));}catch(Exception e){Toast.makeText(owner,e.getMessage(),Toast.LENGTH_LONG).show();}});box.addView(compose);ScrollView scroll=new ScrollView(owner);scroll.addView(box);new AlertDialog.Builder(owner).setTitle("画像の読み取りと訂正").setView(scroll).setPositiveButton("訂正を記録",(d,w)->edit(owner,row)).setNeutralButton("この履歴を削除",(d,w)->new AlertDialog.Builder(owner).setMessage("この読み取り・訂正履歴を削除しますか？ 元写真・会話・予定は削除しません。").setPositiveButton("削除",(q,z)->new Thread(()->{try{ReadingHistory.delete(owner,id);}catch(Exception ignored){}},"DeleteReadingHistory").start()).setNegativeButton("戻る",null).show()).setNegativeButton("閉じる",null).show();});}catch(Exception e){owner.runOnUiThread(()->Toast.makeText(owner,"履歴が更新・削除されています",Toast.LENGTH_LONG).show());}},"ReadingDetail").start();}
 static void edit(MainActivity owner,JSONObject row){LinearLayout box=new LinearLayout(owner);box.setOrientation(1);EditText field=new EditText(owner),before=new EditText(owner),after=new EditText(owner);field.setHint("項目：日付、名前など");before.setHint("変更前：原文の一部（任意）");after.setHint("訂正後");field.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(120)});before.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(1200)});after.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(1200)});box.addView(field);box.addView(before);box.addView(after);String change=java.util.UUID.randomUUID().toString();AlertDialog dialog=new AlertDialog.Builder(owner).setTitle("訂正履歴を追加").setView(box).setPositiveButton("保存",null).setNegativeButton("戻る",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(button->{String f=field.getText().toString(),a=before.getText().toString(),b=after.getText().toString();dialog.getButton(-1).setEnabled(false);new Thread(()->{try{ReadingHistory.correct(owner,row.getString("id"),row.getInt("revision"),change,f,a,b);owner.runOnUiThread(()->{dialog.dismiss();show(owner,row.optString("id"));});}catch(Exception e){owner.runOnUiThread(()->{dialog.getButton(-1).setEnabled(true);after.setError(e.getMessage());});}},"CorrectReading").start();}));dialog.show();}
 private ReadingHistoryDialog(){}
}
